const requests=[
 {id:'SR-1048',subject:'Unable to export monthly usage report',priority:'High',status:'In progress',updated:'18 min ago'},
 {id:'SR-1043',subject:'Update billing contact for our account',priority:'Normal',status:'Waiting on you',updated:'Yesterday'},
 {id:'SR-1039',subject:'SSO configuration assistance',priority:'Normal',status:'In progress',updated:'2 days ago'},
 {id:'SR-1027',subject:'Add users to customer workspace',priority:'Normal',status:'Resolved',updated:'8 Jun 2025'},
 {id:'SR-1018',subject:'Clarification on latest invoice',priority:'Normal',status:'Resolved',updated:'3 Jun 2025'}
];
const pageNames={dashboard:'Dashboard',requests:'Support requests',profile:'My profile',deployment:'Deployment center'};
const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
function row(r){const cls=r.status==='In progress'?'progress':r.status==='Waiting on you'?'waiting':'resolved';return `<tr><td><strong>${esc(r.subject)}</strong>${esc(r.id)}</td><td class="${r.priority==='High'?'priority-high':''}">${esc(r.priority)}</td><td><span class="pill ${cls}">${esc(r.status)}</span></td><td>${esc(r.updated)}</td></tr>`}
function renderRequests(){document.querySelector('#dashboardRequestRows').innerHTML=requests.slice(0,3).map(row).join('');filterRequests()}
function filterRequests(){const query=document.querySelector('#requestSearch').value.toLowerCase();const status=document.querySelector('#statusFilter').value;const result=requests.filter(r=>(r.subject.toLowerCase().includes(query)||r.id.toLowerCase().includes(query))&&(status==='all'||r.status===status));document.querySelector('#allRequestRows').innerHTML=result.length?result.map(row).join(''):'<tr><td colspan="4">No requests match your filters.</td></tr>'}
function navigate(name){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.querySelector(`#${name}Page`).classList.add('active');document.querySelectorAll('.nav-item[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===name));document.querySelector('#pageCrumb').textContent=pageNames[name];document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menuButton').setAttribute('aria-expanded','false');document.querySelector('#main').focus();window.scrollTo(0,0)}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
document.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.page)));
document.querySelectorAll('[data-link-page]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.linkPage)));
document.querySelector('#menuButton').addEventListener('click',e=>{const sidebar=document.querySelector('#sidebar');sidebar.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',sidebar.classList.contains('open'))});
const modal=document.querySelector('#requestModal');
function toggleModal(show){modal.classList.toggle('hidden',!show);if(show)setTimeout(()=>modal.querySelector('input').focus(),0)}
document.querySelectorAll('.new-request').forEach(button=>button.addEventListener('click',()=>toggleModal(true)));
document.querySelectorAll('.modal-close').forEach(button=>button.addEventListener('click',()=>toggleModal(false)));
modal.addEventListener('click',e=>{if(e.target===modal)toggleModal(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')toggleModal(false)});
document.querySelector('#requestForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);requests.unshift({id:`SR-${1049+requests.length}`,subject:data.get('subject'),priority:data.get('priority'),status:'In progress',updated:'Just now'});renderRequests();e.currentTarget.reset();toggleModal(false);toast('Support request submitted successfully')});
document.querySelector('#requestSearch').addEventListener('input',filterRequests);document.querySelector('#statusFilter').addEventListener('change',filterRequests);
const profile=document.querySelector('#profileForm');const initialProfile=new FormData(profile);
profile.addEventListener('submit',e=>{e.preventDefault();toast('Profile changes saved')});
document.querySelector('#resetProfile').addEventListener('click',()=>{for(const [key,value] of initialProfile.entries()){const field=profile.elements[key];if(field)field.value=value}toast('Unsaved changes discarded')});
document.querySelector('#photoButton').addEventListener('click',()=>toast('Photo upload is unavailable in this prototype'));
document.querySelector('#signOut').addEventListener('click',()=>toast('Sign-out flow is simulated in this prototype'));
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function setStep(index,state,label){const step=document.querySelectorAll('.pipeline-step')[index];step.className=`pipeline-step ${state}`;step.querySelector('b').textContent=label;step.querySelector('span').textContent=state==='success'?'✓':state==='failed'?'!':index+1}
document.querySelector('#runDeploy').addEventListener('click',async e=>{e.currentTarget.disabled=true;document.querySelector('#diagnosisEmpty').classList.remove('hidden');document.querySelector('#diagnosisResult').classList.add('hidden');document.querySelector('#pipelineStatus').textContent='Running';for(let i=0;i<4;i++)setStep(i,'','Pending');for(let i=0;i<2;i++){setStep(i,'running','Running');await sleep(650);setStep(i,'success','Passed')}setStep(2,'running','Deploying');await sleep(750);setStep(2,'failed','Failed');document.querySelector('#pipelineStatus').textContent='Failed';document.querySelector('#diagnosisEmpty').classList.add('hidden');document.querySelector('#diagnosisResult').classList.remove('hidden');e.currentTarget.disabled=false;toast('Deployment failure captured for diagnosis')});
document.querySelector('#applyFix').addEventListener('click',async e=>{e.currentTarget.disabled=true;e.currentTarget.textContent='Verifying corrective change…';setStep(2,'running','Retrying');await sleep(800);setStep(2,'success','Passed');setStep(3,'running','Testing');await sleep(800);setStep(3,'success','Passed');document.querySelector('#pipelineStatus').textContent='Verified';e.currentTarget.textContent='Correction verified';toast('Staging health checks passed; release is ready for approval')});
renderRequests();
